const fs = require('fs');
const zlib = require('zlib');
const buf = fs.readFileSync('/var/tmp/avb-runs/avb-3yRDLd/project/site/fonts/acme-sans.woff2');
console.log('signature', buf.toString('ascii',0,4), 'flavor', buf.toString('ascii',4,8), 'len', buf.readUInt32BE(8));
const numTables = buf.readUInt16BE(12);
console.log('numTables', numTables);
const knownTags = ['cmap','head','hhea','hmtx','maxp','name','OS/2','post','cvt ','fpgm','glyf','loca','prep','CFF ','VORG','EBDT','EBLC','gasp','hdmx','kern','LTSH','PCLT','VDMX','vhea','vmtx','BASE','GDEF','GPOS','GSUB','EBSC','JSTF','MATH','CBDT','CBLC','COLR','CPAL','SVG ','sbix','acnt','avar','bdat','bloc','bsln','cvar','fdsc','feat','fmtx','fvar','gvar','hsty','just','lcar','mort','morx','opbd','prop','trak','Zapf','Silf','Glat','Gloc','Feat','Sill'];
let p = 48;
const tables = [];
function readBase128(){let v=0;for(let i=0;i<5;i++){const b=buf[p++];v=(v<<7)|(b&0x7f);if(!(b&0x80))return v;}throw new Error('bad b128');}
for(let i=0;i<numTables;i++){
  const flags=buf[p++]; const idx=flags&0x3f; let tag;
  if(idx===63){tag=buf.toString('ascii',p,p+4);p+=4;} else tag=knownTags[idx];
  const origLength=readBase128();
  const version=flags>>6;
  let transformLength=null;
  if((tag==='glyf'||tag==='loca')?version!==3:version!==0) transformLength=readBase128();
  tables.push({tag,origLength,transformLength,version});
}
console.log(tables);
const compStart=p;
const data=zlib.brotliDecompressSync(buf.subarray(compStart));
console.log('decompressed',data.length);
let off=0;
for(const t of tables){
  const len=t.transformLength!=null?t.transformLength:t.origLength;
  t.offset=off; t.data=data.subarray(off,off+len); off+=len;
}
for(const t of tables){
  if(t.tag==='fvar'){ console.log('fvar present len',t.origLength); }
  if(t.tag==='OS/2'){ const d=t.data; console.log('OS/2 version',d.readUInt16BE(0),'usWeightClass',d.readUInt16BE(4),'usWidthClass',d.readUInt16BE(6),'fsSelection',d.readUInt16BE(62).toString(2)); }
  if(t.tag==='head'){ console.log('head unitsPerEm',t.data.readUInt16BE(18)); }
  if(t.tag==='name'){ /* skip */ }
}
EOF
