function r128(){let v=0;for(let i=0;i<5;i++){const b=buf[p++];v=(v<<7)|(b&0x7f);if(!(b&0x80))return v;}}
for(let i=0;i<numTables;i++){const flags=buf[p++];const idx=flags&0x3f;let tag;if(idx===63){tag=buf.toString('ascii',p,p+4);p+=4;}else tag=knownTags[idx];const origLength=r128();const version=flags>>6;let transformLength=null;if((tag==='glyf'||tag==='loca')?version!==3:version!==0)transformLength=r128();tables.push({tag,origLength,transformLength});}
const data=zlib.brotliDecompressSync(buf.subarray(p)); let off=0;
for(const t of tables){const len=t.transformLength!=null?t.transformLength:t.origLength;t.d=t.data||data.subarray(off,off+len);off+=len;}
const fvar=tables.find(t=>t.tag==='fvar').d;
const axisCount=fvar.readUInt16BE(8), axisSize=fvar.readUInt16BE(10), instanceCount=fvar.readUInt16BE(12), instanceSize=fvar.readUInt16BE(14);
console.log({axisCount,axisSize,instanceCount,instanceSize});
let o=16;
const axes=[];
for(let i=0;i<axisCount;i++){
  const tag=fvar.toString('ascii',o,o+4); const min=fvar.readInt32BE(o+4)/65536, def=fvar.readInt32BE(o+8)/65536, max=fvar.readInt32BE(o+12)/65536;
  axes.push({tag,min,def,max}); o+=axisSize;
}
console.log(axes);
o=16+axisCount*axisSize;
for(let i=0;i<instanceCount;i++){
  const subfamilyNameID=fvar.readUInt16BE(o); const flags=fvar.readUInt16BE(o+2); const coords=[];
  for(let a=0;a<axisCount;a++) coords.push(fvar.readInt32BE(o+4+a*4)/65536);
  console.log('instance',i,{subfamilyNameID,flags,coords}); o+=instanceSize;
}
// name table
const nt=tables.find(t=>t.tag==='name').d;
const count=nt.readUInt16BE(2), strOff=nt.readUInt16BE(4);
for(let i=0;i<count;i++){
  const rec=6+i*12; const platform=nt.readUInt16BE(rec), encoding=nt.readUInt16BE(rec+2), lang=nt.readUInt16BE(rec+4), nameID=nt.readUInt16BE(rec+6), len=nt.readUInt16BE(rec+8), offn=nt.readUInt16BE(rec+10);
  const raw=nt.subarray(strOff+offn,strOff+offn+len);
  let str;
  if(platform===3||platform===0) str=Buffer.from(raw).swap16().toString('utf16le');
  else str=raw.toString('latin1');
  if([1,2,4,6,16,17,21,22,25].includes(nameID)) console.log('name',nameID,'platform',platform,'->',JSON.stringify(str));
}
EOF
