cat > "$TMPDIR/weighttest.js" <<'EOF'
const { chromium } = require('/var/tmp/avb-runs/avb-3yRDLd/project/node_modules/playwright');
(async () => {
  const browser = await chromium.launch();
  const page = await browser.newPage();
  await page.goto('http://127.0.0.1:4173/index.html', { waitUntil: 'networkidle' });
  const out = await page.evaluate(async () => {
    await document.fonts.ready;
    // add a second family with the proper variable weight range
    const ff = new FontFace('Acme Var', 'url(/fonts/acme-sans.woff2)', { weight: '300 900' });
    await ff.load(); document.fonts.add(ff);
    await document.fonts.ready;
    function stats(family, weight, synthesis='auto') {
      const c = document.createElement('canvas'); c.width=600; c.height=120;
      const x = c.getContext('2d', {willReadFrequently:true});
      x.fontSynthesis = synthesis;
      x.fillStyle='#fff'; x.fillRect(0,0,c.width,c.height);
      x.fillStyle='#000'; x.font = `${weight} 80px "${family}"`;
      x.textBaseline='middle'; x.fillText('Handgloves', 10, 60);
      const d = x.getImageData(0,0,c.width,c.height).data;
      let dark=0, sum=0;
      for (let i=0;i<d.length;i+=4){ const v=255-d[i]; dark += v>40?1:0; sum+=v; }
      return {dark, sum};
    }
    const res = {};
    for (const fam of ['Acme Sans','Acme Var']) for (const w of [300,400,700,800]) res[`${fam}-${w}`]=stats(fam,w);
    res['Acme Sans-800-nosynth']=stats('Acme Sans',800,'none');
    res['Acme Var-800-nosynth']=stats('Acme Var',800,'none');
    return res;
  });
  for (const [k,v] of Object.entries(out)) console.log(k.padEnd(28), 'dark', v.dark, 'sum', v.sum);
  await browser.close();
})();
EOF
