cat > "$TMPDIR/cssaudit.js" <<'EOF'
const { chromium } = require('/var/tmp/avb-runs/avb-3yRDLd/project/node_modules/playwright');
(async () => {
  const browser = await chromium.launch();
  const page = await browser.newPage();
  const failures = [];
  page.on('requestfailed', r => failures.push(['failed', r.url(), r.failure()?.errorText]));
  page.on('response', r => { if (r.status() >= 400) failures.push(['status', r.status(), r.url()]); });
  for (const name of ['index','products','pricing','orders','about','contact']) {
    await page.goto(`http://127.0.0.1:4173/${name}.html`, { waitUntil: 'networkidle' });
  }
  const info = await page.evaluate(() => {
    const out = { sheets: [], invalidDecls: [], fontStatus: [] };
    for (const sheet of document.styleSheets) {
      const entry = { href: sheet.href, rules: sheet.cssRules.length };
      out.sheets.push(entry);
      for (const rule of sheet.cssRules) {
        if (rule.style) {
          for (let i = 0; i < rule.style.length; i++) {
            const prop = rule.style[i];
            const val = rule.style.getPropertyValue(prop);
            if (!val || val.includes('undefined')) out.invalidDecls.push({ selector: rule.selectorText, prop, val });
          }
        }
      }
    }
    document.fonts.forEach(f => out.fontStatus.push({ family: f.family, weight: f.weight, status: f.status }));
    return out;
  });
  console.log(JSON.stringify({failures, info}, null, 2));
  await browser.close();
})();
EOF
