input.command:
cat > "$TMPDIR/verify.js" <<'EOF'
const { chromium } = require('/var/tmp/avb-runs/avb-3yRDLd/project/node_modules/playwright');
(async () => {
  const browser = await chromium.launch();
  const page = await browser.newPage();
  await page.goto('http://127.0.0.1:4173/index.html', { waitUntil: 'networkidle' });
  const out = await page.evaluate(async () => {
    await document.fonts.ready;
    const faces = [];
    document.fonts.forEach(f => faces.push({ family: f.family, weight: f.weight, status: f.status }));
    function ink(weight) {
      const c = document.createElement('canvas'); c.width = 600; c.height = 120;
      const x = c.getContext('2d', { willReadFrequently: true });
      x.fillStyle = '#fff'; x.fillRect(0, 0, c.width, c.height);
      x.fillStyle = '#000'; x.font = `${weight} 80px "Acme Sans"`;
      x.textBaseline = 'middle'; x.fillText('Handgloves', 10, 60);
      const d = x.getImageData(0, 0, c.width, c.height).data;
      let sum = 0; for (let i = 0; i < d.length; i += 4) sum += 255 - d[i];
      return sum;
    }
    return { faces, ink: { w400: ink(400), w700: ink(700), w800: ink(800) } };
  });
  console.log(JSON.stringify(out, null, 2));
  await page.screenshot({ path: `${process.env.TMPDIR}/shots/index-fixed.png`, fullPage: true });
  await browser.close();
})();
EOF
PORT=4173 node server.js >"$TMPDIR/server.log" 2>&1 & SRV=$!; sleep 1; node "$TMPDIR/verify.js"; RC=$?; kill $SRV 2>/dev/null; npx playwright test tests/functional.spec.ts 2>&1 | tail -5; exit $RC

